import{_ as i,a8 as o,o as n,c as r,ah as s,K as d}from"./chunks/framework.DG3Ui9QY.js";import"./chunks/theme.DbX6O-_7.js";const b=JSON.parse('{"title":"_agent_scripts","description":"","frontmatter":{},"headers":[],"relativePath":"_agent_scripts/README.md","filePath":"_agent_scripts/README.md","lastUpdated":1789991442000}'),l={name:"_agent_scripts/README.md"};function a(g,e,p,h,u,m){const c=o("NolebaseGitContributors"),t=o("NolebaseGitChangelog");return n(),r("div",null,[e[0]||(e[0]=s(`<h1 id="agent-scripts" tabindex="-1">_agent_scripts <a class="header-anchor" href="#agent-scripts" aria-label="Permalink to “_agent_scripts”">​</a></h1><p>工作区操作/诊断脚本统一存放处（供 agent 调用）。</p><h2 id="脚本清单" tabindex="-1">脚本清单 <a class="header-anchor" href="#脚本清单" aria-label="Permalink to “脚本清单”">​</a></h2><h3 id="test-image-embed-render-ts" tabindex="-1"><code>test_image_embed_render.ts</code> <a class="header-anchor" href="#test-image-embed-render-ts" aria-label="Permalink to “test_image_embed_render.ts”">​</a></h3><p>验证 <code>obsidianImageEmbed</code> 插件在 VitePress 渲染管线中的生效顺序。</p><ul><li>背景：<code>![[Attachments/x.jpg]]</code> 必须抢在 nolebase 的双向链接规则之前拦截，否则被渲染成死链(#)。</li><li>用法：<code>node_modules/.bin/tsx _agent_scripts/test_image_embed_render.ts &lt;old|new&gt;</code><ul><li><code>old</code> = nolebase 先装、obsidianImageEmbed 后装（== 真实 config 顺序），预期 7 <code>&lt;img&gt;</code>、0 死链。</li><li><code>new</code> = obsidianImageEmbed 先装（preConfig 早于 nolebase），用于对比验证锚点顺序。</li></ul></li></ul><h3 id="ai-daily-post-count-chars-py" tabindex="-1"><code>ai_daily_post/count_chars.py</code> <a class="header-anchor" href="#ai-daily-post-count-chars-py" aria-label="Permalink to “ai_daily_post/count_chars.py”">​</a></h3><p>AI 资讯文章字数校验（配合技能 <code>ai-hot-article-daily</code> 使用）。</p><ul><li>模式 1：<code>python count_chars.py &lt;文章.md&gt;</code> —— 统计正文字数（自动剥离 frontmatter/备选标题/引用块/标题行/话题标签区），要求纯中文 &gt;1200。</li><li>模式 2：<code>python count_chars.py --text &quot;&lt;摘要&gt;&quot;</code> —— 按Python len() 口径统计字符数，摘要要求 90–120。</li><li>运行环境：受管 Python 3.13（<code>C:/Users/stars/.workbuddy/binaries/python/versions/3.13.12/python.exe</code>）。</li></ul><h3 id="xhs-card-render-html-py" tabindex="-1"><code>xhs_card/render_html.py</code> <a class="header-anchor" href="#xhs-card-render-html-py" aria-label="Permalink to “xhs_card/render_html.py”">​</a></h3><p>把 HTML 卡片渲染成 PNG（小红书 / 公众号配图产线的核心工具）。</p><ul><li>原理：直接调用 Playwright 缓存里的 Chromium <strong>无头截图</strong>，不依赖 playwright / puppeteer 库；输出尺寸精确等于 <code>--size</code>。</li><li>用法： <ul><li>单文件：<code>python render_html.py card.html --preset xhs</code></li><li>整目录：<code>python render_html.py ./cards --preset xhs --out ./png</code></li><li>尺寸预设：<code>xhs</code> 1080x1440（3:4）、<code>xhs1x1</code> 1080x1080、<code>gzh-cover</code> 900x383（2.35:1）、<code>gzh-body</code> 1080x1440</li><li>高清：<code>--scale 2</code>（默认，输出 2160x2880）；<code>--size 1080x1440</code> 可自定义</li></ul></li><li><strong>坑</strong>：输出路径必须传绝对路径，Chromium 的 <code>--screenshot</code> 对相对路径解析不可靠（脚本内已做 abspath）。</li><li>运行环境：受管 Python 3.13。</li></ul><h3 id="xhs-card-render-deck-py" tabindex="-1"><code>xhs_card/render_deck.py</code> <a class="header-anchor" href="#xhs-card-render-deck-py" aria-label="Permalink to “xhs_card/render_deck.py”">​</a></h3><p>把「多卡片 deck.html」<strong>逐张</strong>渲染成 PNG（一篇文章 = 一套卡片序列的产线工具）。</p><ul><li>适用场景：一个 <code>deck.html</code> 里纵向排 N 张卡片（每张 <code>.card</code>，尺寸=预设宽高），页面支持 <code>#N</code> 锚点只显示第 N 张。脚本先 <code>--dump-dom</code> 数出卡片总数，再逐张带 <code>#N</code> 截图。</li><li>用法： <ul><li><code>python render_deck.py deck.html --preset xhs --out ./png</code></li><li><code>--from 1 --to 3</code> 只渲染第 1~3 张（调试单卡时省时间）</li><li><code>--scale 2</code>（默认高清）；<code>--size 1080x1440</code> 可覆盖预设</li></ul></li><li>输出：<code>deck-01.png</code>、<code>deck-02.png</code> …（编号即卡序）</li><li>为什么不用「截长图再切」：Chromium 单张截图高度上限约 16384px，12 张 × 1440 × 2 倍 = 34560px 会超限。逐张截图长度可控、还能只重跑改动的那几张。</li><li><strong>坑</strong>：数卡片数时不能直接 <code>count(&#39;class=&quot;card&#39;)</code> —— deck.html 的 JS 模板字符串里也有 <code>class=&quot;card</code> 字面量，会把卡片数虚报。必须先 <code>re.sub(r&quot;&lt;script[\\s\\S]*?&lt;/script&gt;&quot;, &quot;&quot;, html)</code> 剥离脚本段再统计（脚本内已处理）。</li><li>依赖：同目录 <code>render_html.py</code> 只是并列关系（各自独立），无 import 依赖。</li><li>运行环境：受管 Python 3.13。</li></ul><h3 id="xhs-card-finalize-unit-py" tabindex="-1"><code>xhs_card/finalize_unit.py</code> <a class="header-anchor" href="#xhs-card-finalize-unit-py" aria-label="Permalink to “xhs_card/finalize_unit.py”">​</a></h3><p>发布单元<strong>收尾</strong>：把渲染出的卡片图并入发布单元、把没用到的素材送回收站（产线最后一步）。</p><ul><li>用法： <ul><li>先干跑：<code>python finalize_unit.py --unit &quot;&lt;发布单元&gt;&quot; --cards &quot;&lt;deck 渲染输出目录&gt;&quot; --trash &lt;未使用文件...&gt; --dry-run</code></li><li>再执行：去掉 <code>--dry-run</code></li><li>卡片处理方式 <code>--mode move</code>（默认）/ <code>copy</code>；命名前缀 <code>--prefix 卡片</code>（默认）</li></ul></li><li>行为：<code>deck-01.png … deck-NN.png</code> → <code>&lt;单元&gt;/assets/卡片_01.png …</code>；<code>总览_deck.png</code> → <code>assets/卡片_总览.png</code>；<code>--trash</code> 列出的文件逐个送 Windows 回收站。</li><li><strong>坑 1（重要）</strong>：<code>send2trash</code> 的 <code>win.legacy</code> 实现（未装 pywin32 时）在部分环境会「<strong>回收成功却抛 WinError 2 / FileNotFoundError</strong>」。所以判据不能看异常，只能看「操作后源文件是否消失」。脚本已按此容错。彻底规避：给 venv 装 <code>pywin32</code>，send2trash 自动切到 <code>win.modern</code>（IFileOperation）。</li><li><strong>坑 2</strong>：回收 ≠ 永久删除，<code>--trash</code> 一律走回收站；执行前务必先 <code>--dry-run</code> 列清单确认。</li><li>运行环境：受管 venv <code>C:/Users/stars/.workbuddy/binaries/python/envs/default/Scripts/python.exe</code>（该 venv 已装 <code>send2trash</code> + <code>pywin32</code>）。</li></ul><h3 id="encoding-guard-py" tabindex="-1"><code>encoding_guard.py</code> <a class="header-anchor" href="#encoding-guard-py" aria-label="Permalink to “encoding_guard.py”">​</a></h3><p>文本文件<strong>编码守卫</strong>：扫描目录列出所有非 UTF-8 文本文件，并可按需原地转码为 UTF-8。</p><ul><li>背景：本项目多数工具<strong>覆写已存在文件时会沿用该文件原编码</strong>。原本以 GBK 落盘的中文 md，改完内容后仍是 GBK，Obsidian 按 UTF-8 读即整篇乱码（新建文件不受影响，默认 UTF-8）。</li><li>用法： <ul><li>体检：<code>python encoding_guard.py &lt;路径或文件&gt;</code>（有非 UTF-8 时退出码 1，可当门禁）</li><li>修复：<code>python encoding_guard.py &lt;路径&gt; --fix --backup</code>（GBK/GB18030/BOM → 纯 UTF-8）</li><li>预览：加 <code>--dry-run</code> 只打印；<code>--ext .md,.txt</code> 自定义扩展名</li></ul></li><li>行为：自动跳过 <code>.git</code> / <code>node_modules</code> / <code>.obsidian</code> / <code>$RECYCLE.BIN</code> 等；「未知编码」（UTF-8、GBK 都解不开）只报告不修改；转码为字节级重编码，不动换行符。</li><li>运行环境：受管 Python 3.13（仅用标准库）。</li></ul><h3 id="mem-index-py" tabindex="-1"><code>mem_index.py</code> <a class="header-anchor" href="#mem-index-py" aria-label="Permalink to “mem_index.py”">​</a></h3><p>记忆库<strong>索引生成 / 校验</strong>（<code>E:\\knowledge\\vault\\Memory</code> 各层 <code>_index.md</code>）。</p><ul><li>背景：手工索引必然漂移（<code>Home.md</code> 曾落后实盘 4~5 条）。故把索引变成<strong>派生物</strong>：frontmatter + 正文首段 → 各层 <code>_index.md</code>，根治漂移。</li><li>用法： <ul><li>生成/更新：<code>python mem_index.py --write</code>（幂等；<strong>新增笔记自动补行/删行，已有行手工写的「定位 / 关键词」原样保留</strong>，可放心润色）</li><li>体检门禁：<code>python mem_index.py --check</code>（报告「缺索引 / 缺失行 / 失效行 / 手工地图页漏列顶层项」，有漂移退出码 1）</li><li>单层：<code>--layer Lessons</code>（可选 <code>Preferences</code> / <code>Plans</code> / <code>Lessons</code> / <code>Workflows</code> / <code>Projects</code>）</li></ul></li><li>覆盖范围：<code>Preferences</code> <code>Plans</code> <code>Lessons</code> <code>Workflows</code> <code>Projects</code>（<strong><code>Decisions</code> 除外</strong>——<code>Rule.md</code> §9 规定其专用格式，勿用本脚本覆盖）。</li><li>顺带校验两张<strong>手工</strong>地图页是否漏列顶层项：<code>vault/_index.md</code>（vault 顶层 25 项）、<code>Memory/_index.md</code>。</li><li><strong>顶层项口径</strong>（<code>top_entries()</code>）：<strong>排除点开头的项</strong> —— <code>.git</code> / <code>.obsidian</code> / <code>.trash</code> 等属工具与仓库基础设施，不算「内容」。2026-09-21 在 <code>Memory/</code> 内建独立本地 git 仓后，多出的 <code>.git</code> 曾让 <code>--check</code> 报「地图页漏列」而<strong>假红</strong>。</li><li>一句话定位取值优先级：frontmatter <code>summary</code> / <code>description</code> → 正文首个实质段落（截 62 字）。</li><li><strong>坑</strong>：<code>_index.md</code> 的表头说明由脚本模板生成，直接手改表头会在下次 <code>--write</code> 时被覆盖——要改表头请改脚本里的 <code>EXTRA_NOTE</code>；表格<strong>数据行</strong>的手工内容是安全的。</li><li>运行环境：受管 Python 3.13（仅标准库）。</li></ul><h3 id="todo-audit-py" tabindex="-1"><code>todo_audit.py</code> <a class="header-anchor" href="#todo-audit-py" aria-label="Permalink to “todo_audit.py”">​</a></h3><p>记忆库<strong>待办归档体检</strong>（<code>Memory/Todo.md</code>）——把「<strong>完成 = 移走</strong>」变成可校验项。</p><ul><li>背景（2026-09-21）：索引漂移有 <code>mem_index.py --check</code>、断链有 <code>link_audit.py</code>、删文件有 <code>ref_scan.py</code>，唯独「待办 → 项目 <code>working/completed.md</code>」这一环<strong>只写在会话收尾 checklist 里、零门禁</strong> → 静默积累 4 条「已标完成却未移走」的条目（含一条 2000 字符、与 <code>completed.md</code> 完全重复的复盘）。根因之一：<code>Rule.md</code>「写入」第 2 条写「<strong>移入</strong>」，而「会话收尾」① 只写「<strong>追加到</strong>」——差一个动词，归档就只做了一半，且收尾时读的正是 ①。</li><li>用法： <ul><li>体检：<code>python todo_audit.py</code>（报告默认写 <code>_agent_scripts/_out/todo_audit.txt</code>）</li><li>门禁：<code>python todo_audit.py --check</code>（有违规则退出码 1）</li><li>其余：<code>-o &lt;文件&gt;</code> / <code>--json</code> / <code>--todo &lt;路径&gt;</code> / <code>--quiet</code></li></ul></li><li>检查三件事：① <strong>完成信号残留</strong> —— 带 <code>✅</code> <code>✔</code> <code>已执行完毕</code> <code>已完成：</code> <code>已结清</code> <code>已归档</code> 等强标记却未移走的条目（引用块说明行与「不再继续」删除线留档<strong>单独计数、不拦门禁</strong>）② <strong>分组名 ↔ <code>Projects/</code> 目录名映射</strong> —— 规则要求分组标题一律取目录名，否则归档无处落地 ③ <strong><code>working/completed.md</code> 是否存在</strong> —— 归档前需先建</li><li><strong>坑 1</strong>：本机 PowerShell 会吞 stdout → 默认写文件再 Read 读回（与 <code>link_audit.py</code> 同）。</li><li><strong>坑 2</strong>：强信号词会命中<strong>指针行</strong> —— 在 Todo 里写归档指引要用「记录见 / 详情见」，别写「已归档」，否则自己把自己判成违规（本次实测踩到）。</li><li>运行环境：受管 Python 3.13（仅标准库）。</li></ul><h3 id="mem-git-py" tabindex="-1"><code>mem_git.py</code> <a class="header-anchor" href="#mem-git-py" aria-label="Permalink to “mem_git.py”">​</a></h3><p>记忆库<strong>独立本地仓</strong>工具（<code>vault/Memory</code>）——把「记忆库有版本历史、且永不上云」变成可执行、可校验。</p><ul><li>背景（2026-09-21 用户裁定）：记忆库此前<strong>零版本保护</strong>（父仓 <code>.gitignore</code> 整体忽略，<code>ls-files</code> 0 个），改错无处回溯。方案：在 <code>Memory/</code> 内建<strong>独立本地仓</strong>，不配任何远端。</li><li>用法： <ul><li>状态：<code>python mem_git.py</code>（报告默认写 <code>_agent_scripts/_out/mem_git.txt</code>）</li><li><strong>收尾 / 季度门禁</strong>：<code>python mem_git.py --check --structure-only</code>（只验结构，不因「有未提交改动」而红）</li><li>完整门禁：<code>python mem_git.py --check</code>（「有未提交改动」<strong>也算违规</strong>、退出码 1 —— 设计如此，别当故障）</li><li>提交：<code>python mem_git.py commit -m &quot;…&quot;</code>（一条命令 <code>add -A</code> + commit，无改动自动跳过）；<code>-F &lt;文件&gt;</code> 从文件读消息（自动容忍 BOM）</li><li>重建：<code>python mem_git.py init</code>（幂等：init + 仓库配置 + <code>.gitignore</code> + 两个守卫）；<code>lockdown</code>（应急清远端 + 重装拒推钩子）</li></ul></li><li><strong>三道保险</strong>：① 不配远端 ② 本层 <code>.git/hooks/pre-push</code> 一律拒绝推送 ③ 父仓 <code>.git/hooks/pre-commit</code> <strong>顶部</strong>插私有面守卫，拒绝任何触碰 <code>vault/Memory</code> 的提交。</li><li><strong>钩子必须「只用 shell 内建」</strong>：用探针钩子实测该环境 PATH 里<strong>没有 <code>grep</code> / <code>date</code> / <code>wc</code></strong>（msys 的 <code>/usr/bin</code> 不在 PATH）→ 用外部命令写的守卫会<strong>静默失效</strong>。附带发现：父仓原 <code>pre-commit</code> 里拦 100 MB 大文件的 <code>wc -c</code> 因此<strong>从未生效</strong>。</li><li><strong>父仓守卫必须插在钩子顶部，不能追加到末尾</strong>：原钩子末尾是 <code>git diff --cached --name-only | while read f; do … done</code>——管道里的 <code>exit 1</code> 只终止<strong>子 shell</strong>，追加在其后会让大文件拦截静默解除。</li><li><strong><code>git add -f</code> 的两种形态</strong>（2026-09-21 实测）：① 加<strong>单个文件</strong> <code>vault/Memory/x.md</code> → <strong>静默不入暂存</strong>（嵌套仓被 git 当嵌入式仓库，退出码 0、暂存区为空 = 典型「假成功」）② 加<strong>整个目录</strong> <code>vault/Memory</code> → 生成 <strong>gitlink</strong>，暂存名 <code>vault/Memory</code>（<strong>不带斜杠</strong>）。守卫正则必须两形态都覆盖。</li><li>实测端到端：暂存 gitlink 后真实 <code>git commit</code> 被拦下、<strong>HEAD 未变、无提交产生</strong>；<code>git push</code> 被拒（退出码 1）；提交消息前 3 字节非 <code>ef bb bf</code>（无 BOM）。</li><li>注：这是<strong>嵌套在父仓内的独立仓</strong>，父仓 <code>git status</code> 看不到它；钩子不在版本库里，换机器跑一次 <code>init</code> 重装。</li><li>运行环境：受管 Python 3.13（仅标准库）。</li></ul><h3 id="ref-scan-py" tabindex="-1"><code>ref_scan.py</code> <a class="header-anchor" href="#ref-scan-py" aria-label="Permalink to “ref_scan.py”">​</a></h3><p>删除笔记/目录前的<strong>引用面扫描</strong>（回答「这个文件能安全删吗？删了会留下什么」）。</p><ul><li>背景：<code>vault/AGENT.md</code> 的删除清理——除用户已知的 <code>vault/Home.md</code> 外，另在 <code>rules/</code> 8 个文件的 frontmatter <code>related:</code> 里藏着引用，手工漏查风险高。故把「删前先扫引用面」固化成一条命令。</li><li>扫描三个面： <ol><li><strong>笔记面</strong> —— 全 vault md 里的 wikilink（区分「带路径引用」与「裸名引用」；裸名会额外提示<strong>同名歧义</strong>）</li><li><strong>仓库面</strong> —— <code>.gitignore</code> 命中情况（是否已忽略、删后是否影响 git 与发布）</li><li><strong>站点面</strong> —— <code>.vitepress/</code> 与 <code>scripts/</code> 里对目标名的字面硬引用</li></ol></li><li>用法： <ul><li><code>python ref_scan.py &lt;路径&gt;</code>（路径可为文件或目录；目录会展开其下所有 md）</li><li><code>-o report.md</code> 写文件（<strong>本机 PowerShell 会吞 stdout，实操建议一律带 <code>-o</code></strong>）</li><li><code>--json</code> 机器可读；<code>--vault</code> / <code>--root</code> 覆盖默认根</li></ul></li><li>退出码：0 = 可安全删除；1 = 存在引用或目标不存在（可当门禁）。</li><li><strong>坑（已处理）</strong>：① <code>[[...]]</code> 出现在<strong>行内代码 / 代码块</strong>里时 Obsidian <strong>不解析</strong>（文档举例文字），必须剥离后再统计，否则大量误报（实测 5 处举例被误判为真引用）；② 带路径的引用（含 <code>/</code>）<strong>不得</strong>退化到同名匹配，否则 <code>[[Memory/AGENTS]]</code> 会误命中根目录的 <code>AGENTS.md</code>。</li><li>运行环境：受管 Python 3.13（仅标准库）。</li></ul><h3 id="link-audit-py" tabindex="-1"><code>link_audit.py</code> <a class="header-anchor" href="#link-audit-py" aria-label="Permalink to “link_audit.py”">​</a></h3><p>全库 wikilink <strong>断链审计</strong>（区分「活链」与「记录文本」，供&quot;改前出清单 / 改后验收&quot;两端使用）。</p><ul><li>背景：批 B 断链修复需要先筛选再改。旧口径统计出「622 个断链」几乎不可用——含大量误报，直接照修会污染素材。</li><li>用法： <ul><li><code>python link_audit.py</code> —— 全库报告写入 <code>_agent_scripts/_out/link_audit.txt</code></li><li><code>python link_audit.py --layers Memory,Knowledge</code> —— 只看指定顶层目录的断链</li><li><code>-o &lt;文件&gt;</code> 指定输出；<code>--quiet</code> 只打印计数</li></ul></li><li><strong>四个必踩的口径陷阱（均已内建处理）</strong>： <ol><li><strong>代码块 / 行内代码里的 <code>[[...]]</code></strong> Obsidian 不解析 —— 不剥离必然误报（实测 <code>ref_scan.py</code> 同类问题少报 5 处、本脚本旧口径虚增 500+）</li><li><strong>判定表必须收录全库所有文件</strong>（笔记 <strong>+ 附件</strong>）—— 只收 <code>.md</code> 会把 <code>![[image.png]]</code> 全部误判为断链</li><li><strong><code>[[Note]]</code> 与 <code>[[Note.md]]</code> 两种写法都有效</strong>，且 Windows 下大小写不敏感（<code>[[todo]]</code> 命中 <code>Todo.md</code>）</li><li><strong>站点视角漏报</strong> —— 判定表是全库的，站点却只发布 <code>PUBLISHED_DIRS</code>。目标<strong>只在非发布目录</strong>（<code>Resources/</code> <code>Archive/</code> <code>Canvas/</code> <code>DailyNotes/</code>）里有同名文件时，Obsidian 算活链、<strong>站点是死链</strong>。本脚本把它单列为输出第二段「站点侧死链」，并只报「引用方在发布层」的（否则 <code>DailyNotes/</code>→<code>DailyNotes-MOC</code> 202 处噪声会淹没真问题）。发布面从 <code>.vitepress/config.ts</code> <strong>正则抽取</strong>，不手工维护。</li></ol></li><li>输出分两段：<code>## 一、真断链（全库无同名文件）</code> / <code>## 二、站点侧死链（只在非发布目录里有同名 → 站点 404）</code>。</li><li>实测基线（2026-09-21 批 B 执行后）：md 1589 篇 / wikilink 2814 条 / <strong>断链目标 103 / 命中 339 行</strong>（改前 141 / 405）；<strong>站点侧死链 6 目标 / 28 行</strong>。</li><li>处置清单见 <code>vault/Memory/Projects/knowledge/断链修复筛选清单-2026-09-21.md</code>。</li><li>运行环境：受管 Python 3.13（仅标准库）。</li></ul><h3 id="debug-ruler-ts" tabindex="-1"><code>debug_ruler.ts</code> <a class="header-anchor" href="#debug-ruler-ts" aria-label="Permalink to “debug_ruler.ts”">​</a></h3><p>探查 VitePress markdown-it 内联规则链（<code>__rules__</code>），定位 nolebase 双向链接规则的真实名字（当前为 <code>bi_directional_link_replace</code>）。</p><ul><li>用法：<code>node_modules/.bin/tsx _agent_scripts/debug_ruler.ts</code></li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li>这些脚本仅用于本地诊断，<strong>不参与站点构建</strong>（不在 <code>vault/</code> 下，VitePress 不会渲染）。</li><li><code>createMarkdownRenderer</code> 有模块级缓存，两种顺序需分两次进程运行。</li><li>顶层 await 在 <code>tsx -e</code> 的 cjs 输出下会报错，故一律用 <code>.ts</code> 文件方式运行。</li></ul><h2 id="入库与提交-本目录的-git-约定" tabindex="-1">入库与提交（本目录的 git 约定） <a class="header-anchor" href="#入库与提交-本目录的-git-约定" aria-label="Permalink to “入库与提交（本目录的 git 约定）”">​</a></h2><ul><li><strong><code>.gitignore</code> 用「忽略目录内容 + 白名单」，不要写「忽略整个目录」</strong>：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>_agent_scripts/*</span></span>
<span class="line"><span>!_agent_scripts/*.py</span></span>
<span class="line"><span>!_agent_scripts/*.ts</span></span>
<span class="line"><span>!_agent_scripts/*.md</span></span>
<span class="line"><span>_agent_scripts/_tmp*</span></span></code></pre></div>写成 <code>_agent_scripts/</code>（目录级忽略）会让 <code>git add</code> <strong>静默跳过脚本本体</strong> —— 提交照样成功、消息还能写「新增 X 脚本」，而 X 从未进库。<strong>2026-09-21 实测踩到</strong>：有一次提交标题为「新增待办归档体检工具 todo_audit.py」，<code>git show --stat</code> 实际只有 <code>README.md</code> 12 行，5 个 py（<code>encoding_guard</code> / <code>link_audit</code> / <code>mem_index</code> / <code>ref_scan</code> / <code>todo_audit</code>）全在库外，且 <code>git status</code> 显示 clean（被忽略故不列出）→ <strong>典型的假成功</strong>。 末行 <code>_tmp*</code> <strong>后置反排除</strong>是必需的：白名单 <code>*.py</code> 会连带放行临时脚本 <code>_tmp*.py</code>（靠 gitignore「最后匹配者胜」压回）。</li><li><strong>核验「有没有入库」要看 <code>git ls-files</code>，不是 <code>git status</code></strong> —— 被忽略的文件在 <code>status</code> 里根本不会出现，<code>git status</code> clean ≠ 文件已入库。若要判单个文件，用 <code>git ls-files --error-unmatch &lt;path&gt;</code> <strong>看退出码</strong>（该命令会把失败原因写到 stderr，合并 2&gt;&amp;1 再加 <code>-ne &quot;&quot;</code> 判断会得到「全部已跟踪」的假结论）。</li><li><strong>提交消息文件别用 PowerShell <code>Set-Content -Encoding UTF8</code> 生成</strong>（PS 5.1 会写 BOM）→ <code>git commit -F</code> 后消息<strong>首字符变成 <code>\\ufeff</code></strong>。用 Python <code>encoding=&quot;utf-8&quot;, newline=&quot;\\n&quot;</code> 写、或 <code>[IO.File]::WriteAllText</code> 配无 BOM 编码；校验：<code>git cat-file commit HEAD</code> 取消息段，前 3 字节不应是 <code>ef bb bf</code>。</li><li><strong>git 的中文输出经 PowerShell 捕获会显示成乱码</strong>（<code>鏂板</code> 之类），那是 PS 5.1 控制台编码假象，<strong>不代表库数据损坏</strong>。要复核编码就用 Python <code>subprocess.run(..., capture_output=True)</code> + <code>decode(&quot;utf-8&quot;)</code>，不要凭 PowerShell 的回显下结论。</li></ul>`,43)),d(c),d(t)])}const k=i(l,[["render",a]]);export{b as __pageData,k as default};
